<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { listReviews, type ReviewRow } from '../api/review'
import { stateLabel } from '../api/manuscripts'
const rows = ref<ReviewRow[]>([]), page = ref(1), total = ref(0), q = ref(''), status = ref('PENDING'), loading = ref(false), error = ref('')
let generation = 0
async function load(reset = false) { if (reset) page.value = 1; const current = ++generation; loading.value = true; error.value = ''; try { const result = await listReviews(page.value, q.value, status.value); if (generation === current) { rows.value = result.items; total.value = result.total } } catch (failure) { if (current === generation) error.value = failure instanceof Error ? failure.message : '读取失败' } finally { if (current === generation) loading.value = false } }
onMounted(() => load())
</script>
<template><div class="panel"><div class="list-filters"><el-input v-model="q" placeholder="搜索送审标题" aria-label="搜索送审标题" @keyup.enter="load(true)" /><el-select v-model="status" aria-label="审核状态" @change="load(true)"><el-option label="待审核" value="PENDING" /><el-option label="已处理" value="DECIDED" /><el-option label="全部送审" value="" /></el-select><el-button @click="load(true)">查询</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-table v-loading="loading" :data="rows" empty-text="暂无符合条件的送审稿件"><el-table-column prop="title" label="送审标题" min-width="240" /><el-table-column prop="organizationName" label="组织" width="150" /><el-table-column label="版本" width="75"><template #default="{row}">第{{ row.versionNo }}版</template></el-table-column><el-table-column label="人工状态" width="90"><template #default="{row}">{{ stateLabel[row.status] }}</template></el-table-column><el-table-column label="检测状态" width="110"><template #default="{row}">{{ stateLabel[row.detectionStatus] || row.detectionStatus }}</template></el-table-column><el-table-column label="送审时间" width="180"><template #default="{row}">{{ new Date(row.submittedAt).toLocaleString('zh-CN') }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><RouterLink :to="`/reviews/${row.submissionId}`">查看审核</RouterLink></template></el-table-column></el-table><el-pagination v-if="total > 20" v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next, total" @current-change="load()" /></div></template>
